 if(draft)host.querySelector('h3').nextElementSibling.textContent=t('在此按箱唛分组并选择资料，随页面提交一次保存。不同组可复用同一份资料。','박스 표시별 그룹과 자료를 입력하면 페이지 제출 시 함께 저장됩니다. 자료를 여러 그룹에서 재사용할 수 있습니다.');
 host.append(form);const status=form.querySelector('[data-status]'),rows=form.querySelector('[data-rows]');const planIds=[];let groupSequence=saved?.groups.length||0,uploadQueue=Promise.resolve(),uploading=0;const groupJobs=new Map();
 function files(target,ids){if(!r.files.length){target.textContent=t('暂无资料，请先在上方上传。','자료가 없습니다. 위에서 먼저 업로드하세요.');return;}for(const f of r.files){const label=document.createElement('label');label.className='cargo-file';label.innerHTML='<input type="checkbox" value="'+e(f.id)+'" '+(ids.includes(f.id)?'checked':'')+'> <span>'+e(f.file_name)+'<small> '+e(f.created_at)+' · '+e(f.uploaded_by)+'</small></span>';target.append(label);}}
