  if(draft){const booking=document.createElement('div');booking.className='cargo-group-reservations';booking.innerHTML='<div data-reservation-list></div><button type="button" data-add-reservation>'+t('＋添加本组出库计划（可选）','그룹 출고 계획 추가 (선택)')+'</button>';direct.after(booking);const list=booking.querySelector('[data-reservation-list]');let sequence=0;booking.querySelector('[data-add-reservation]').onclick=()=>{const row=document.createElement('details');row.className='cargo-group-reservation';const number=++sequence;row.open=true;row.innerHTML='<summary>'+t('本次出库计划','이번 출고 계획')+'</summary>'+reservationHTML()+'<button type="button" data-remove-reservation>'+t('移除此预约','예약 삭제')+'</button>';const summarize=()=>{const q=row.querySelector('[data-reservation=quantity]').value,u=row.querySelector('[data-reservation=unit]').value,date=row.querySelector('[data-reservation=expected_ship_at]').value;row.querySelector('summary').textContent=t('出库计划 ','출고 계획 ')+number+' · '+(q&&u?q+u:t('数量待确认','수량 미정'))+(date?' · '+date:'');};row.addEventListener('input',summarize);row.addEventListener('change',summarize);summarize();row.querySelector('[data-remove-reservation]').onclick=()=>row.remove();list.append(row);row.querySelector('[data-reservation=expected_ship_at]').focus();};section._readReservations=()=>[...list.children].map(readReservation);}

